#!/usr/bin/env node
// PreToolUse(Edit|Write|MultiEdit|NotebookEdit): protect secrets and generated files.
import { block, readInput, rel } from "./lib.mjs";

const input = readInput();
const file = rel(input.tool_input?.file_path ?? input.tool_input?.notebook_path ?? "");

if (/(^|\/)\.env(\..+)?$/.test(file) && !file.endsWith(".env.example")) {
  block(`Blocked: ${file} holds secrets. Edit .env.example instead and tell the user which variable to set.`);
}
if (file.startsWith("drizzle/")) {
  block(
    `Blocked: ${file} is generated by drizzle-kit and migrations are append-only. ` +
      "Change src/db/schema.ts and run `npm run db:generate -- --name <change>` instead.",
  );
}
if (file === "package-lock.json") block("Blocked: don't hand-edit package-lock.json; use npm install/uninstall.");
if (file.startsWith(".git/")) block("Blocked: don't edit files inside .git/.");
if (file.startsWith("node_modules/")) block("Blocked: don't edit node_modules; change our code or pin a version.");
